CREATE TABLE brand_assignments(tenant_id text NOT NULL,brand_id text NOT NULL,object_id text NOT NULL,kind text NOT NULL CHECK(kind IN('preset','visual_identity')),object_revision integer NOT NULL,revision integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,brand_id,object_id),FOREIGN KEY(tenant_id,brand_id) REFERENCES catalog_items(tenant_id,id),FOREIGN KEY(tenant_id,object_id) REFERENCES catalog_items(tenant_id,id));
CREATE TABLE connections(id text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id),brand_id text,kind text NOT NULL,label text NOT NULL,config jsonb NOT NULL DEFAULT '{}',secret_ciphertext text NOT NULL,status text NOT NULL DEFAULT 'configured',revision integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,brand_id) REFERENCES catalog_items(tenant_id,id));
CREATE TABLE integration_accounts(id text NOT NULL,tenant_id text NOT NULL,brand_id text NOT NULL,connection_id text NOT NULL,provider_account_id text NOT NULL,label text NOT NULL,platform text NOT NULL,connected boolean NOT NULL DEFAULT true,capabilities jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,brand_id) REFERENCES catalog_items(tenant_id,id),FOREIGN KEY(tenant_id,connection_id) REFERENCES connections(tenant_id,id));
CREATE TABLE artifacts(id text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id),brand_id text,object_id text,revision integer NOT NULL,kind text NOT NULL,relative_path text NOT NULL,sha256 text NOT NULL,byte_size bigint NOT NULL,mime_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,brand_id) REFERENCES catalog_items(tenant_id,id));
CREATE TABLE provider_jobs(id text NOT NULL,tenant_id text NOT NULL,connection_id text NOT NULL,item_id text NOT NULL,revision integer NOT NULL,scene_id text NOT NULL,stage text NOT NULL,status text NOT NULL DEFAULT 'prepared',provider_id text,request_hash text NOT NULL,result jsonb,error_code text,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,item_id,revision,scene_id,stage),FOREIGN KEY(tenant_id,connection_id) REFERENCES connections(tenant_id,id),FOREIGN KEY(tenant_id,item_id) REFERENCES content_items(tenant_id,id));
CREATE TABLE content_revisions(tenant_id text NOT NULL,item_id text NOT NULL,revision integer NOT NULL,snapshot jsonb NOT NULL,created_by text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,item_id,revision),FOREIGN KEY(tenant_id,item_id) REFERENCES content_items(tenant_id,id));
CREATE TABLE idempotency_records(tenant_id text NOT NULL,operation text NOT NULL,key text NOT NULL,payload_hash text NOT NULL,response jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,operation,key));
CREATE TABLE notification_preferences(tenant_id text NOT NULL,user_id text NOT NULL,connection_id text,chat_id text,verified boolean NOT NULL DEFAULT false,enabled boolean NOT NULL DEFAULT true,quiet_start text,quiet_end text,timezone text NOT NULL DEFAULT 'Asia/Jakarta',events jsonb NOT NULL DEFAULT '["error","recovered","ready"]',PRIMARY KEY(tenant_id,user_id),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,connection_id) REFERENCES connections(tenant_id,id));
CREATE TABLE telegram_verification_challenges(tenant_id text NOT NULL,user_id text NOT NULL,challenge_hash text NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,user_id),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE TABLE login_attempts(key text PRIMARY KEY,attempts integer NOT NULL DEFAULT 0,window_started_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX runs_due ON automation_runs(status,next_attempt_at,created_at);
CREATE INDEX catalog_domain ON catalog_items(tenant_id,domain,archived);
CREATE INDEX audit_brand_time ON audit_events(tenant_id,brand_id,created_at);
